SELECT traficsourceid, searchengineid, advengineid, src_referer, url, COUNT(*) AS PageViews FROM (SELECT traficsourceid, searchengineid, advengineid, CASE WHEN (searchengineid = 0 AND advengineid = 0) THEN referer ELSE '' END AS src_referer, url FROM hits WHERE counterid = 62 AND eventdate >= '2013-07-01' AND eventdate <= '2013-07-31' AND isrefresh = 0) t GROUP BY traficsourceid, searchengineid, advengineid, src_referer, url ORDER BY PageViews DESC, url, src_referer LIMIT 10 OFFSET 1000;
